"""Extract uniquely located passages from the exact bytes of a pinned PDF.

Selectors are reviewed caller input. Matching a passage checks a transcription;
it does not authenticate the authors, establish causality, or interpret a base.
"""

from __future__ import annotations

import fcntl
import hashlib
import os
import re
import stat
import subprocess
import tempfile
from dataclasses import dataclass
from contextlib import contextmanager
from pathlib import Path


class SourceAuditError(ValueError):
    """A source or uniquely located passage does not satisfy its contract."""


@dataclass(frozen=True)
class SourceSpec:
    bytes: int
    sha256: str


@dataclass(frozen=True)
class ExtractorSpec:
    path: Path
    sha256: str


# Reviewed local Linux default. Other installations must supply a reviewed pin.
DEFAULT_EXTRACTOR = ExtractorSpec(
    Path("/usr/bin/pdftotext"),
    "0fb98ea179e19154a90202608c164f2a319b79f16576fa6534b2d601033565e7",
)

# Candidate installation profile: explicit opt-in, never derived from host bytes.
# Its extraction comparison is retained under goals/autonomous-software-v1.
_INSTALLATION_PROFILES = {
    "cachyos-26.08.0-x86_64-v4": ExtractorSpec(
        Path("/usr/bin/pdftotext"),
        "47253257c7a7995ea6c8ad54b47b0edece8739dd4102c7bcd5a729472c386fb4",
    ),
}


def configured_extractor(
    fallback: ExtractorSpec = DEFAULT_EXTRACTOR, *, profile: str | None = None,
) -> ExtractorSpec:
    """Select an explicit fixed pin; absence preserves the caller's contract.

    Profiles identify installation bytes, not method acceptance or authenticated
    host libraries. Unknown/empty profile names reject rather than fall back.
    """
    name = os.environ.get("SPECORGANON_EXTRACTOR_PROFILE") if profile is None else profile
    if name is None:
        return fallback
    try:
        return _INSTALLATION_PROFILES[name]
    except KeyError as exc:
        raise SourceAuditError(f"unknown extractor profile: {name!r}") from exc

# Linux constants are absent from some supported CPython 3.11 builds.
_F_ADD_SEALS = getattr(fcntl, "F_ADD_SEALS", 1033)
_F_SEALS = (getattr(fcntl, "F_SEAL_WRITE", 0x08)
            | getattr(fcntl, "F_SEAL_GROW", 0x04)
            | getattr(fcntl, "F_SEAL_SHRINK", 0x02)
            | getattr(fcntl, "F_SEAL_SEAL", 0x01))


@dataclass(frozen=True)
class PdfPages:
    pages: tuple[str, ...]
    source_sha256: str
    source_bytes: int
    text_sha256: str
    extractor_version: str
    extractor_path: str
    extractor_sha256: str


def normalize_whitespace(text: str) -> str:
    """Collapse whitespace only; preserve numbers, punctuation and dash types."""
    return re.sub(r"\s+", " ", text).strip()


@contextmanager
def _sealed_extractor(spec: ExtractorSpec):
    """Execute the verified binary bytes, without a second path lookup."""
    if not all(hasattr(os, name) for name in ("memfd_create", "MFD_CLOEXEC", "MFD_ALLOW_SEALING")):
        raise SourceAuditError("runtime lacks sealed memfd extractor support")
    if (not spec.path.is_absolute()
            or re.fullmatch(r"[0-9a-f]{64}", spec.sha256) is None):
        raise SourceAuditError("extractor needs an absolute path and reviewed digest")
    sealed = None
    try:
        fd = os.open(spec.path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd, "rb") as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or not 0 < info.st_size <= 20_000_000:
                raise SourceAuditError("extractor is not a bounded regular file")
            raw = stream.read(20_000_001)
        if hashlib.sha256(raw).hexdigest() != spec.sha256:
            raise SourceAuditError("extractor bytes differ from reviewed digest")
        sealed = os.memfd_create("organon-pdftotext", os.MFD_CLOEXEC | os.MFD_ALLOW_SEALING)
        with os.fdopen(os.dup(sealed), "wb") as stream:
            stream.write(raw)
        os.fchmod(sealed, 0o500)
        fcntl.fcntl(sealed, _F_ADD_SEALS, _F_SEALS)
        yield f"/proc/self/fd/{sealed}", sealed
    except OSError as exc:
        raise SourceAuditError("cannot capture and seal reviewed extractor") from exc
    finally:
        if sealed is not None:
            os.close(sealed)


def read_pdf_pages(
    path: Path, spec: SourceSpec, extractor: ExtractorSpec | None = None,
) -> PdfPages:
    """Hash once, then extract a private snapshot of those same source bytes."""
    # An explicit caller pin always wins; environment cannot bypass its check.
    if extractor is None:
        extractor = configured_extractor()
    if (type(spec.bytes) is not int or not 0 < spec.bytes <= 20_000_000
            or not isinstance(spec.sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", spec.sha256) is None):
        raise SourceAuditError("invalid PDF source pin")
    try:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd, "rb") as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_size != spec.bytes:
                raise SourceAuditError("PDF source size/type differs from pin")
            raw = stream.read(spec.bytes + 1)
    except OSError as exc:
        raise SourceAuditError(f"cannot read pinned PDF: {path.name}") from exc
    if len(raw) != spec.bytes or hashlib.sha256(raw).hexdigest() != spec.sha256:
        raise SourceAuditError("PDF source bytes differ from pin")
    try:
        with _sealed_extractor(extractor) as (executable, fd), tempfile.TemporaryDirectory(
            prefix="organon-source-passage-",
        ) as folder:
            snapshot = Path(folder) / "source.pdf"
            snapshot.write_bytes(raw)
            env = {"PATH": "/usr/bin:/bin", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8"}
            extracted = subprocess.run(
                [str(extractor.path), "-layout", "-enc", "UTF-8", str(snapshot), "-"],
                executable=executable, pass_fds=(fd,), env=env,
                capture_output=True, timeout=20, check=True,
            )
            version = subprocess.run(
                [str(extractor.path), "-v"], executable=executable, pass_fds=(fd,), env=env,
                capture_output=True, timeout=5, check=True,
            )
        version_text = (version.stdout + version.stderr).decode("utf-8").splitlines()[0]
        text = extracted.stdout.decode("utf-8")
    except (OSError, subprocess.SubprocessError, UnicodeError, IndexError) as exc:
        raise SourceAuditError("Poppler pdftotext extraction failed") from exc
    if not text or len(extracted.stdout) > 2_000_000:
        raise SourceAuditError("PDF extraction empty or too large")
    pages = text.split("\f")
    if pages and not pages[-1].strip():
        pages.pop()
    if not pages or any(not page.strip() for page in pages):
        raise SourceAuditError("PDF extraction contains an empty page")
    return PdfPages(
        tuple(pages), spec.sha256, len(raw),
        hashlib.sha256(extracted.stdout).hexdigest(), version_text,
        str(extractor.path), extractor.sha256,
    )


def extract_passage(
    pdf: PdfPages, page: int, start: str, end: str, pattern: str,
    required: tuple[str, ...] = (),
) -> dict:
    """Require one page, one pair of anchors, and exactly one regex match.

    Passage/match digests use whitespace-normalized UTF-8; the page digest
    uses raw extracted UTF-8. Neither is a digest of the original PDF bytes.
    """
    if type(page) is not int or not 1 <= page <= len(pdf.pages):
        raise SourceAuditError("PDF page outside extracted source")
    raw = pdf.pages[page - 1]
    text = normalize_whitespace(raw)
    begin, finish = normalize_whitespace(start), normalize_whitespace(end)
    if not begin or not finish or text.count(begin) != 1:
        raise SourceAuditError("start locator missing or ambiguous")
    if text.count(finish) != 1:
        raise SourceAuditError("end locator missing or ambiguous")
    tail = text.split(begin, 1)[1]
    if tail.count(finish) != 1:
        raise SourceAuditError("end locator missing or ambiguous")
    passage = begin + " " + tail.split(finish, 1)[0].strip()
    for context in required:
        if normalize_whitespace(context) not in passage:
            raise SourceAuditError("required unit/base/provenance context missing")
    try:
        matches = list(re.finditer(pattern, passage))
    except re.error as exc:
        raise SourceAuditError("invalid reviewed passage pattern") from exc
    if len(matches) != 1 or not matches[0].groupdict():
        raise SourceAuditError("numeric locator missing, ambiguous or unnamed")
    if any(value is None for value in matches[0].groupdict().values()):
        raise SourceAuditError("numeric locator has unmatched groups")
    match = matches[0].group(0)
    return {
        "source_sha256": pdf.source_sha256,
        "page": page,
        "page_sha256": hashlib.sha256(raw.encode()).hexdigest(),
        "passage_sha256": hashlib.sha256(passage.encode()).hexdigest(),
        "matched_sha256": hashlib.sha256(match.encode()).hexdigest(),
        "normalization": "whitespace_only",
        "groups": matches[0].groupdict(),
        "matched_text": match,
    }
"""Audit the exposed bread transcription against pinned PDF passages.

The published numbers are extracted, never taken from a numeric answer table.
Semantic bases/provenance are checked against an explicitly reviewed contract.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import sys
from decimal import Decimal
from pathlib import Path

from specorganon.source_passages import (
    ExtractorSpec, SourceAuditError, SourceSpec, configured_extractor,
    extract_passage, read_pdf_pages,
)


ROOT = Path(__file__).resolve().parents[1]
DEFAULT_CLAIMS = ROOT / "cases/bread_development/source_claims.json"
DEFAULT_TABLE = ROOT / "cases/bread_norway/survey_table1.json"
DEFAULT_PDFS = ROOT / "cases/bread_norway"
CONTRACT = ROOT / "experiments/development/bread_source_audit_2026-09-30/contract.json"


def _unique_pairs(pairs: list[tuple[str, object]]) -> dict:
    result = {}
    for key, value in pairs:
        if key in result:
            raise SourceAuditError(f"duplicate JSON key: {key}")
        result[key] = value
    return result


def _reject_constant(value: str) -> None:
    raise SourceAuditError(f"nonfinite JSON number: {value}")


def _load(path: Path) -> tuple[dict, dict]:
    try:
        raw = path.read_bytes()
        if len(raw) > 131_072:
            raise SourceAuditError("JSON input too large")
        value = json.loads(raw, object_pairs_hook=_unique_pairs, parse_constant=_reject_constant)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise SourceAuditError(f"cannot read valid JSON: {path.name}") from exc
    if type(value) is not dict:
        raise SourceAuditError("JSON input must be an object")
    return value, {"bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()}


def _same(actual: object, expected: object, label: str) -> None:
    # JSON serialization also distinguishes booleans from integers in metadata.
    if json.dumps(actual, sort_keys=True, allow_nan=False) != json.dumps(
        expected, sort_keys=True, allow_nan=False,
    ):
        raise SourceAuditError(f"reviewed unit/base/locator/provenance differs: {label}")


def _numeric(value: object, label: str) -> Decimal:
    if type(value) not in (int, float):
        raise SourceAuditError(f"numeric claim has invalid type: {label}")
    result = Decimal(str(value))
    if not result.is_finite():
        raise SourceAuditError(f"numeric claim not finite: {label}")
    return result


def audit_bread_sources(
    claims_path: Path = DEFAULT_CLAIMS, table_path: Path = DEFAULT_TABLE,
    pdf_root: Path = DEFAULT_PDFS, *, extractor_profile: str | None = None,
) -> dict:
    contract, contract_pin = _load(CONTRACT)
    contract_extractor = ExtractorSpec(Path(contract["extractor"]["path"]),
                                       contract["extractor"]["sha256"])
    profile_name = (extractor_profile if extractor_profile is not None
                    else os.environ.get("SPECORGANON_EXTRACTOR_PROFILE"))
    extractor = (contract_extractor if profile_name is None
                 else configured_extractor(contract_extractor, profile=profile_name))
    claims, claims_pin = _load(claims_path)
    table, table_pin = _load(table_path)
    expected_claim_fields = set(contract["claim_document_metadata"]) | {"sources", "claims"}
    if set(claims) != expected_claim_fields:
        raise SourceAuditError("claim document fields differ")
    _same({k: claims[k] for k in contract["claim_document_metadata"]},
          contract["claim_document_metadata"], "claim document")
    _same(claims["sources"], contract["sources"], "PDF source identity")
    if set(table) != set(contract["survey_metadata"]) | {"reported_total", "categories"}:
        raise SourceAuditError("survey document fields differ")
    _same({k: table[k] for k in contract["survey_metadata"]},
          contract["survey_metadata"], "survey identity/measure")

    if type(claims["claims"]) is not list:
        raise SourceAuditError("claims must be a list")
    indexed = {}
    for item in claims["claims"]:
        if type(item) is not dict or type(item.get("key")) is not str:
            raise SourceAuditError("claim shape/key invalid")
        key = item["key"]
        if key in indexed or key not in contract["claims"]:
            raise SourceAuditError("claim key duplicate or unregistered")
        metadata = contract["claims"][key]["metadata"]
        if set(item) != set(metadata) | {"key", "value"}:
            raise SourceAuditError("claim fields differ")
        _same({k: item[k] for k in metadata}, metadata, key)
        _numeric(item["value"], key)
        indexed[key] = item
    if set(indexed) != set(contract["claims"]):
        raise SourceAuditError("claim set incomplete")

    categories = table["categories"]
    expected_categories = contract["survey_categories"]
    if type(categories) is not list or len(categories) != len(expected_categories):
        raise SourceAuditError("survey categories incomplete")
    for row, expected in zip(categories, expected_categories, strict=True):
        if type(row) is not dict or set(row) != set(expected) | {"count", "reported_percent"}:
            raise SourceAuditError("survey row fields differ")
        _same({k: row[k] for k in expected}, expected, "survey row/bounds")
        if type(row["count"]) is not int or row["count"] < 0:
            raise SourceAuditError("survey count must be a nonnegative integer")
        if (type(row["reported_percent"]) is not str
                or re.fullmatch(r"\d+\.\d", row["reported_percent"]) is None):
            raise SourceAuditError("survey percentage must be a printed decimal string")
    if type(table["reported_total"]) is not int or table["reported_total"] <= 0:
        raise SourceAuditError("survey total must be a positive integer")

    pdfs = {
        name: read_pdf_pages(pdf_root / identity["visible_file"],
                             SourceSpec(identity["bytes"], identity["sha256"]),
                             extractor)
        for name, identity in contract["sources"].items()
    }
    passages = {}
    for name, selector in contract["selectors"].items():
        pdf = pdfs[selector["source"]]
        page = selector["page"]
        # These fixed articles have physical and printed pagination in agreement.
        if re.search(rf"\b{page} of \d+\b", pdf.pages[page - 1].splitlines()[0]) is None:
            raise SourceAuditError("printed and physical page disagree")
        try:
            passages[name] = extract_passage(
                pdf, page, selector["start"], selector["end"], selector["pattern"],
                tuple(selector["required"]),
            )
        except SourceAuditError as exc:
            raise SourceAuditError(f"{name}: {exc}") from exc
    verified = {}
    for key, binding in contract["claims"].items():
        passage = passages[binding["selector"]]
        extracted = Decimal(passage["groups"][binding["group"]])
        if _numeric(indexed[key]["value"], key) != extracted:
            raise SourceAuditError(f"PDF value differs from transcription: {key}")
        verified[key] = {
            **binding["metadata"], "value": str(extracted),
            "passage": binding["selector"], "passed": True,
        }
    total_groups = passages["survey_total"]["groups"]
    extracted_total = int(total_groups["survey_respondents"])
    if table["reported_total"] != extracted_total:
        raise SourceAuditError("survey total differs from PDF")
    verified_rows = []
    for row in categories:
        selector_name = "survey_" + row["key"]
        groups = passages[selector_name]["groups"]
        if row["count"] != int(groups["count"]) or row["reported_percent"] != groups["percent"]:
            raise SourceAuditError(f"survey row differs from PDF: {row['key']}")
        if Decimal(row["reported_percent"]) != Decimal(row["count"]) * 100 / extracted_total:
            raise SourceAuditError("survey printed percentage inconsistent with count")
        verified_rows.append({**row, "passage": selector_name, "passed": True})
    if (sum(row["count"] for row in categories) != extracted_total
            or sum(Decimal(row["reported_percent"]) for row in categories)
            != Decimal(total_groups["total_percent"])
            or Decimal(total_groups["total_percent"]) != 100):
        raise SourceAuditError("survey totals inconsistent")

    prose = passages["survey_prose"]["groups"]["bins"]
    prose_intervals = re.findall(r"\d+–\d+|more than \d+", prose)
    table_intervals = [re.sub(r" slices$", "", row["label"]).casefold()
                       for row in categories if "–" in row["label"] or "More than" in row["label"]]
    warnings = []
    if prose_intervals != table_intervals:
        warnings.append({
            "code": "survey_prose_table_category_disagreement", "source": "survey",
            "prose_page": 3, "table_page": 4, "prose_bins": prose,
            "table_bins": [row["label"] for row in categories],
            "decision": "transcribe Table 1; preserve disagreement, no silent reconciliation",
        })
    prose_table = passages["waste_cross_reference"]["groups"]["table"]
    waste_table = contract["claims"]["retail_bread_waste"]["metadata"]["locator"]["table"]
    if prose_table != waste_table:
        warnings.append({
            "code": "lca_prose_table_cross_reference_disagreement", "source": "lca",
            "prose_page": 7, "prose_table": prose_table, "verified_table": waste_table,
            "decision": "locate Table 7 on page 8; preserve prose cross-reference error",
        })
    return {
        "schema": 1, "study_id": "D100", "passed": True,
        "scope": "published transcription fidelity, not field resolution or causal validity",
        "verified_claims": len(verified), "verified_survey_rows": len(verified_rows),
        "base_validation": "reviewed_contract_consistency",
        "input_pins": {"claims": claims_pin, "table": table_pin, "contract": contract_pin},
        "extractor_selection": {
            "profile": profile_name,
            "profile_review_status": ("historical_contract_pin" if profile_name is None
                                      else "candidate_pending_independent_review"),
            "contract_path": str(contract_extractor.path),
            "contract_sha256": contract_extractor.sha256,
            "historical_binary_reproduced": extractor == contract_extractor,
            "scope": "binary pin only; host libraries and full historical text not authenticated",
        },
        "source_extraction": {
            name: {"bytes": pdf.source_bytes, "sha256": pdf.source_sha256,
                   "text_sha256": pdf.text_sha256, "pages": len(pdf.pages),
                   "extractor_version": pdf.extractor_version,
                   "extractor_path": pdf.extractor_path,
                   "extractor_sha256": pdf.extractor_sha256,
                   "extractor_execution": "sealed_memfd_verified_binary",
                   "host_shared_libraries_authenticated": False}
            for name, pdf in pdfs.items()
        },
        "claims": verified, "survey_rows": verified_rows, "passages": passages,
        "survey_total": extracted_total, "warnings": warnings, "limits": contract["limits"],
        "Q": None, "field_intervention": False, "global_acceptance": "0/5",
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--claims", type=Path, default=DEFAULT_CLAIMS)
    parser.add_argument("--table", type=Path, default=DEFAULT_TABLE)
    parser.add_argument("--pdf-root", type=Path, default=DEFAULT_PDFS)
    parser.add_argument("--output", type=Path)
    parser.add_argument("--extractor-profile", help="Explicit registered installation profile")
    args = parser.parse_args(argv)
    try:
        result = audit_bread_sources(args.claims, args.table, args.pdf_root,
                                    extractor_profile=args.extractor_profile)
        rendered = json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False) + "\n"
        if args.output:
            with args.output.open("x", encoding="utf-8") as stream:
                stream.write(rendered)
        else:
            sys.stdout.write(rendered)
    except (SourceAuditError, OSError) as exc:
        print(f"source audit rejected: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

